
/* STATE */
const state={page:'home',user:null,theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light',mobile:false,guests:2,filters:{type:'All types',status:'All',min:0,max:800,capacity:1,amenities:[],sort:'Recommended'},filterMore:false,view:'grid',favorites:new Set(),compare:new Set(),roomId:1,customerTab:'Bookings',bookingTab:'Upcoming',adminTab:'Overview',modal:null,bookingDraft:null,bookingStep:1,hero:0,testimonial:0,faqOpen:null,notifications:false,profileEdit:false,roomSearch:'',customerSearch:'',bookingsFilter:'All',roomsLoading:false,roomsLoaded:false,searchDates:null,adminStats:null,customers:[],notificationsList:[]};
/* MOCK DATA */
let rooms=[];
let reviews=[];
let bookings=[];
const features=[['✧','A stay shaped around you','Personal touches and thoughtful service make every visit feel entirely your own.'],['⌁','A sense of place','Discover the character of the city through design, flavor, and local recommendations.'],['◌','Room to exhale','Quiet spaces, beautifully layered comfort, and rituals that help you truly unwind.'],['♨','Wellness, your way','Restore your rhythm with treatments, movement, and moments of stillness.'],['♧','Good things, close by','From the first coffee to a late supper, find something lovely around every corner.'],['♡','Here when you need us','Our team is available around the clock to make everything feel effortless.']];

/* UTILITIES */
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];const money=n=>'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:0});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const todayISO=()=>new Date().toISOString().slice(0,10);const datePlus=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};const nights=(a,b)=>Math.max(1,Math.round((new Date(b)-new Date(a))/86400000));const toast=(msg,type='info')=>{const el=document.createElement('div');el.className='toast '+type;el.textContent=(type==='success'?'✓  ':type==='error'?'!  ':'✦  ')+msg;$('#toast-stack').append(el);setTimeout(()=>el.remove(),3500)};const statusTag=s=>`<span class="tag ${s==='Confirmed'||s==='Available'||s==='Completed'?'green':s==='Cancelled'||s==='Maintenance'?'red':'gold'}">${esc(s)}</span>`;const initials=name=>name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
function getRoom(id){return rooms.find(r=>r.id===+id)}
function appShell(content){return `${navbar()}<main>${content}</main>${state.page==='login'||state.page==='register'?'':footer()}${state.modal?modalHTML():''}`}
function navbar(){const u=state.user;return `<header class="topbar" id="topbar"><div class="wrap nav-inner"><a class="brand" href="#" data-page="home" aria-label="StayEase home"><span class="brand-icon">🏨</span><span><span class="stay">Stay</span><span class="ease">Ease</span></span></a><nav class="nav-links"><a href="#" data-page="home" class="${state.page==='home'?'active':''}">Home</a><a href="#" data-page="rooms" class="${state.page==='rooms'?'active':''}">Stay with us</a><a href="#amenities" data-scroll="amenities">Experiences</a><a href="#footer" data-scroll="footer">Our story</a></nav><div class="nav-actions"><button class="icon-btn" data-action="theme" aria-label="Toggle color theme">${state.theme==='dark'?'☀':'☾'}</button>${u?`<button class="icon-btn" data-action="notifications" aria-label="Notifications">♧</button><span class="role-pill">${u.role}</span><button class="btn btn-ghost btn-sm guest-only" data-page="dashboard">${u.role==='admin'?'Admin':'My stay'}</button><button class="btn btn-outline btn-sm guest-only" data-action="logout">Sign out</button>`:`<button class="btn btn-ghost btn-sm guest-only" data-page="login">Sign in</button><button class="btn btn-primary btn-sm guest-only" data-page="register">Join us</button>`}<button class="icon-btn hamburger" data-action="mobile" aria-label="Open menu">☰</button></div></div><div class="mobile-links ${state.mobile?'open':''}"><a href="#" data-page="home">Home</a><a href="#" data-page="rooms">Stay with us</a><a href="#amenities" data-scroll="amenities">Experiences</a>${u?`<a href="#" data-page="dashboard">${u.role==='admin'?'Admin dashboard':'My stay'}</a><button data-action="logout">Sign out</button>`:`<a href="#" data-page="login">Sign in</a><a href="#" data-page="register">Join us</a>`}</div></header>${state.notifications&&u?`<div class="modal-backdrop" data-action="close-notifications"><div class="modal" style="position:absolute;right:7%;top:82px;width:340px" data-stop><div class="modal-head"><h2>For you</h2><button class="icon-btn" data-action="notifications">×</button></div><div class="modal-body"><div class="notification"><span>✦</span><div><b>Your next stay is waiting</b><small>Take a look at the details for your November escape.</small></div></div><div class="notification"><span>♡</span><div><b>A little something for you</b><small>Enjoy 15% off your next visit with STAY15.</small></div></div></div></div></div>`:''}`}
function footer(){return `<footer class="footer" id="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="#" data-page="home"><span class="brand-icon">🏨</span><span><span class="stay">Stay</span><span class="ease">Ease</span></span></a><p style="max-width:280px;margin-top:15px">A thoughtful place to pause, reconnect, and make a little more room for the moments that matter.</p><p>⌖ 18 Willow Lane, San Francisco, CA</p></div><div><h4>Explore</h4><div class="footer-links"><a href="#" data-page="rooms">Our rooms</a><a href="#amenities" data-scroll="amenities">Experiences</a><a href="#faq" data-scroll="faq">FAQs</a></div></div><div><h4>Get in touch</h4><div class="footer-links"><a href="mailto:hello@stayease.com">hello@stayease.com</a><a href="tel:+14155550128">+1 (415) 555-0128</a><a href="#">Instagram　 Pinterest</a></div></div><div><h4>Need a hand?</h4><p>Our team is happy to help make your stay feel effortless.</p><a href="mailto:hello@stayease.com">Contact StayEase</a></div></div><div class="footer-bottom"><span>© 2026 StayEase. Made for getting away.</span><span>Privacy　·　Terms　·　Accessibility</span></div></div></footer>`}
/* HOME */
function homePage(){const slides=[['A slower kind of luxury','Where Every Stay Becomes a Memory','Find your own rhythm in a place made for meaningful moments, thoughtful comforts, and the pleasure of feeling at home.'],['A room to call your own','Come away. Feel closer.','Whether it is a weekend or a little longer, settle into a stay that feels effortlessly yours.'],['The good kind of getaway','Make space for the moment','Discover warm hospitality, considered design, and the little details that turn a trip into a story.']];const s=slides[state.hero%slides.length];return `<section class="hero"><div class="hero-bg" id="hero-bg"></div><div class="wrap"><div class="hero-content"><span class="eyebrow" style="color:var(--gold-light)">${s[0]}</span><h1 class="serif">${s[1].replace('Memory','<span>Memory</span>').replace('closer.','<span>closer.</span>').replace('moment','<span>moment</span>')}</h1><p class="hero-copy">${s[2]}</p><div class="hero-actions"><button class="btn btn-primary" data-page="rooms">Discover your stay <span>→</span></button><a class="btn btn-outline" href="#our-story" data-scroll="our-story">Our story</a></div><div class="hero-dots">${slides.map((_,i)=>`<button class="hero-dot ${i===state.hero?'active':''}" data-action="hero" data-index="${i}" aria-label="Show slide ${i+1}"></button>`).join('')}</div></div></div></section><div class="wrap"><div class="search-card reveal"><div class="field"><label for="search-in">Check in</label><input id="search-in" type="date" min="${todayISO()}" value="${datePlus(1)}"></div><div class="field"><label for="search-out">Check out</label><input id="search-out" type="date" min="${datePlus(2)}" value="${datePlus(2)}"></div><div class="field"><label>Guests</label><div class="stepper"><button data-action="guest-minus" aria-label="Fewer guests">−</button><span id="guest-count">${state.guests} guests</span><button data-action="guest-plus" aria-label="More guests">+</button></div></div><div class="field"><label for="search-type">Room preference</label><select id="search-type"><option>All types</option>${['Standard','Deluxe','Suite'].map(t=>`<option>${t}</option>`).join('')}</select></div><button class="btn btn-primary" data-action="search">Find your room　→</button></div></div><section class="wrap section" id="our-story"><div class="stats-strip reveal">${[[rooms.length,'Rooms & suites',''],[reviews.length,'Guest reviews','+'],[reviews.length?reviews.reduce((sum,review)=>sum+Number(review.rating||0),0)/reviews.length:0,'Average rating',''],[15,'Years of welcome','']].map((x,i)=>`<div class="stat"><strong data-count="${x[0]}" data-suffix="${x[2]}">0</strong><span>${x[1]}</span></div>`).join('')}</div><div class="section-head" style="margin-top:94px"><div><span class="eyebrow">The StayEase feeling</span><h2 class="serif">More than a place<br>to lay your head.</h2></div><p>We believe the best stays give you more than a key. They leave you with the feeling of being looked after, and a little more connected to the place around you.</p></div><div class="feature-grid">${features.map(f=>`<article class="feature-card reveal"><div class="feature-icon">${f[0]}</div><h3>${f[1]}</h3><p>${f[2]}</p></article>`).join('')}</div></section><section class="section" style="background:var(--paper)"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Rooms for your kind of getaway</span><h2 class="serif">Find your own<br>favorite corner.</h2></div><button class="btn btn-outline" data-page="rooms">Explore all rooms　→</button></div><div class="room-grid">${rooms.slice(0,3).map(roomCard).join('')}</div></div></section><section class="wrap section" id="amenities"><div class="section-head"><div><span class="eyebrow">Little luxuries, lovely rituals</span><h2 class="serif">Settle into the<br>StayEase way.</h2></div><p>Space to slow down, and everything close at hand. Your stay comes with the thoughtful extras that make the time away feel even better.</p></div><div class="amenity-grid">${[['🏊','Pool'],['🧖','Spa'],['🍽️','Restaurant'],['🏋️','Fitness room'],['⌁','Complimentary WiFi'],['🚘','Airport pickup']].map(a=>`<div class="amenity-item reveal"><span>${a[0]}</span><p>${a[1]}</p></div>`).join('')}</div></section><section class="wrap section" style="padding-top:10px"><div class="offers reveal"><div><span class="eyebrow" style="color:var(--gold-light)">A little more time for you</span><h2>Stay 3 nights, save 15%.</h2><p>Make a long weekend of it. Book three nights and let the fourth day take care of itself.</p></div><div class="promo-chip">STAY15 <button class="btn btn-sm btn-primary" data-action="copy-promo">Copy code</button></div></div></section><section class="section" style="background:var(--paper)"><div class="wrap center"><span class="eyebrow">Notes from our guests</span><div class="testimonial-wrap" style="margin-top:23px"><button class="icon-btn slider-arrow left" data-action="testimonial-prev" aria-label="Previous review">←</button>${testimonialCard()}<button class="icon-btn slider-arrow right" data-action="testimonial-next" aria-label="Next review">→</button></div></div></section><section class="wrap section"><div class="newsletter reveal"><div><h2>Something lovely in your inbox.</h2><p>Occasional notes from us, with thoughtful offers and reasons to get away.</p></div><form class="newsletter-form" id="newsletter-form"><input type="email" name="email" placeholder="Your email address" required aria-label="Email address"><button class="btn btn-primary">Sign me up　→</button></form></div></section><section class="section" id="faq" style="background:var(--paper)"><div class="wrap"><div class="section-head center"><div><span class="eyebrow">Good to know</span><h2 class="serif">A few helpful details.</h2></div></div><div class="faq-list">${[['What time are check-in and check-out?','Check-in begins at 3:00 PM, and we kindly ask guests to check out by 11:00 AM. We are always happy to arrange an early arrival or a later departure when available.'],['What is your cancellation policy?','Plans change. Cancel free of charge up to 48 hours before arrival. Cancellations within 48 hours are subject to the first night’s room rate.'],['Can I bring my pet?','We welcome well-behaved dogs in select rooms with a small nightly fee. Please let us know ahead of time so we can prepare a warm welcome.'],['Is parking available?','Valet parking is available around the clock for $35 per night. Electric vehicle charging is available on request.']].map((f,i)=>`<div class="faq-item ${state.faqOpen===i?'open':''}"><button class="faq-q" data-action="faq" data-index="${i}">${f[0]}<span>${state.faqOpen===i?'−':'+'}</span></button><div class="faq-a">${f[1]}</div></div>`).join('')}</div></div></section>`}
function testimonialCard(){const t=[['“The kind of place that makes you forget to check your phone. Our room, the people, the little welcome note — everything felt special.”','Sofia Ramirez','Stayed in October'],['“Warm, unhurried, and beautifully designed. We came for a weekend and wished we had booked a week.”','Elliot Brooks','Stayed in September'],['“A perfect city escape. Breakfast was wonderful and the team remembered our names by day two.”','Amara Johnson','Stayed in August']][state.testimonial%3];return `<article class="testimonial"><div class="stars">★★★★★</div><blockquote>${t[0]}</blockquote><div class="guest"><div class="avatar">${initials(t[1])}</div><div><strong>${t[1]}</strong><small>${t[2]}</small></div></div></article>`}
function roomCard(r){return `<article class="room-card"><div class="room-art" style="background:${r.art}"><span class="art-emoji">${r.emoji}</span><span class="tag ${r.status==='Available'?'green':'red'}">${r.status}</span><button class="heart ${state.favorites.has(r.id)?'active':''}" data-action="favorite" data-id="${r.id}" aria-label="Toggle favorite">${state.favorites.has(r.id)?'♥':'♡'}</button></div><div class="room-body"><div class="room-meta"><span>${r.type} · Up to ${r.capacity} guests</span><span class="rating">★ ${r.rating} <span class="muted">(${r.reviews})</span></span></div><h3>${r.name}</h3><p>${r.description.slice(0,108)}…</p><div class="amenity-tags">${r.amenities.slice(0,3).map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="room-foot"><span class="price">${money(r.price)} <small>/ night</small></span><div class="room-actions"><button class="btn btn-outline btn-sm" data-page="details" data-id="${r.id}">View</button><button class="btn btn-primary btn-sm" data-action="book" data-id="${r.id}">Book</button></div></div></div></article>`}
/* ROOMS */
function filteredRooms(){return rooms.filter(r=>(state.filters.type==='All types'||r.type===state.filters.type)&&(state.filters.status==='All'||r.status===state.filters.status)&&r.price>=state.filters.min&&r.price<=state.filters.max&&r.capacity>=state.filters.capacity&&state.filters.amenities.every(a=>r.amenities.some(x=>x.toLowerCase().includes(a.toLowerCase())))&&(!state.searchDates||(!bookings.some(b=>b.roomId===r.id&&b.status==='Confirmed'&&state.searchDates.cin<b.checkout&&state.searchDates.cout>b.checkin)&&!r.booked.some(day=>{const start=new Date(state.searchDates.cin),end=new Date(state.searchDates.cout),date=new Date(start.getFullYear(),start.getMonth(),day);return start.getMonth()===10&&start.getFullYear()===2026&&date>=start&&date<end})))).sort((a,b)=>state.filters.sort==='Price: low to high'?a.price-b.price:state.filters.sort==='Price: high to low'?b.price-a.price:state.filters.sort==='Rating'?b.rating-a.rating:state.filters.sort==='Capacity'?b.capacity-a.capacity:0)}
function roomsPage(){const list=filteredRooms();if(state.roomsLoading)return `<section class="page"><div class="wrap"><div class="page-title"><span class="eyebrow">Find your room</span><h1>Make yourself at home.</h1><p>Choose a room that feels right for the way you want to get away.</p></div><div class="room-grid">${[1,2,3].map(()=>`<div class="room-card"><div class="skeleton" style="height:196px"></div><div class="room-body"><div class="skeleton" style="height:12px;width:45%;border-radius:5px"></div><div class="skeleton" style="height:24px;width:70%;margin:15px 0;border-radius:5px"></div><div class="skeleton" style="height:40px;border-radius:5px"></div></div></div>`).join('')}</div></div></section>`;return `<section class="page"><div class="wrap"><div class="page-title"><span class="eyebrow">Find your room</span><h1>Make yourself at home.</h1><p>Choose a room that feels right for the way you want to get away. Each one has its own point of view, and the same warm welcome.</p></div><div class="filter-panel"><div class="field"><label>Room type</label><select data-filter="type"><option>All types</option>${['Standard','Deluxe','Premium','Suite','Family'].map(t=>`<option ${state.filters.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Availability</label><select data-filter="status"><option>All</option><option ${state.filters.status==='Available'?'selected':''}>Available</option><option ${state.filters.status==='Maintenance'?'selected':''}>Maintenance</option></select></div><div class="field"><label>Max price · ${money(state.filters.max)}</label><input type="range" min="100" max="800" step="10" value="${state.filters.max}" data-filter="max" style="accent-color:var(--gold);padding:8px 0"></div><div class="field"><label>Guests</label><select data-filter="capacity">${[1,2,3,4,5].map(n=>`<option value="${n}" ${state.filters.capacity===n?'selected':''}>${n}+ guests</option>`).join('')}</select></div><div class="field"><label>Sort by</label><select data-filter="sort">${['Recommended','Price: low to high','Price: high to low','Rating','Capacity'].map(x=>`<option ${state.filters.sort===x?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn btn-outline btn-sm" data-action="toggle-filter-more">${state.filterMore?'Less filters':'More filters'}</button><button class="btn btn-ghost btn-sm" data-action="clear-filters">Clear</button></div>${state.filterMore?`<div class="filter-more">${['King bed','Sea view','Garden view','Breakfast','Pool access','Balcony','Kitchenette','Workspace'].map(a=>`<label class="check-label"><input type="checkbox" data-amenity="${a}" ${state.filters.amenities.includes(a)?'checked':''}>${a}</label>`).join('')}</div>`:''}<div class="results-line"><span>${list.length} rooms to make your own${state.compare.size?` · ${state.compare.size} selected to compare`:''}</span><div class="view-switch"><button class="${state.view==='grid'?'active':''}" data-action="view-grid">▦</button><button class="${state.view==='list'?'active':''}" data-action="view-list">☰</button></div></div><div class="${state.view==='grid'?'room-grid':'rooms-list'}">${list.length?list.map(r=>`<div>${roomCard(r)}<div style="padding:0 15px 13px;background:var(--paper)"><label class="check-label"><input type="checkbox" data-compare="${r.id}" ${state.compare.has(r.id)?'checked':''} ${state.compare.size>=3&&!state.compare.has(r.id)?'disabled':''}> Add to compare</label></div></div>`).join(''):`<div class="empty-state"><div>⌂</div><h3 class="serif">No rooms found just yet.</h3><p>Try widening your search or clearing a filter to see more lovely places to stay.</p><button class="btn btn-outline" data-action="clear-filters">Clear filters</button></div>`}</div>${state.compare.size?`<div class="compare-dock"><span>${state.compare.size} room${state.compare.size===1?'':'s'} selected</span><button class="btn btn-primary btn-sm" data-action="compare">Compare rooms</button><button class="btn btn-ghost btn-sm" data-action="clear-compare">Clear</button></div>`:''}</div></section>`}
/* ROOM DETAILS */
function detailsPage(){const r=getRoom(state.roomId)||rooms[0];return `<section class="page"><div class="wrap"><button class="btn btn-ghost btn-sm" data-page="rooms">← Back to rooms</button><div class="detail-layout" style="margin-top:15px"><div><div class="gallery"><div class="detail-art" style="background:${r.art}">${r.emoji}</div><div class="detail-art" style="background:linear-gradient(135deg,#dac7a8,#98856b)">🛏️</div><div class="detail-art" style="background:linear-gradient(135deg,#c3d6c0,#759276)">🌿</div><div class="detail-art" style="background:linear-gradient(135deg,#e2d4bf,#bd9f79)">🛁</div><div class="detail-art" style="background:linear-gradient(135deg,#b8cfd3,#779ba0)">☕</div></div><div class="detail-copy"><div class="room-meta" style="margin-top:20px"><span>${r.type} · Up to ${r.capacity} guests</span><span class="rating">★ ${r.rating} <span class="muted">(${r.reviews} reviews)</span></span></div><h1>${r.name}</h1><p>${r.description} Every detail is designed to make your time away feel easy, from the generous linens to the small comforts waiting when you arrive.</p><h3>Thoughtful comforts</h3><div class="amenities-full">${['🛏️ '+r.amenities[0],'🌅 '+r.amenities[1],'🛁 '+r.amenities[2],'☕ '+r.amenities[3],'📶 Complimentary WiFi','🧴 Premium bath amenities','❄️ Climate control','🛎️ 24-hour room service'].map(x=>`<span>${x}</span>`).join('')}</div><h3>A few helpful notes</h3><div class="rules-grid"><div class="rule">↗ Check-in from 3:00 PM · Check-out by 11:00 AM</div><div class="rule">♡ Free cancellation up to 48 hours before arrival</div><div class="rule">⌂ Non-smoking room · Pets welcome in select rooms</div><div class="rule">♧ Complimentary WiFi and daily housekeeping</div></div><h3>Availability · November 2026</h3>${calendarHTML(r)}<h3>Guests have loved their stay</h3><div class="review"><div class="review-head"><strong>Guest rating <span class="rating">★ ${r.rating} / 5</span></strong><span class="muted">${r.reviews} reviews</span></div>${[['Cleanliness',96],['Comfort',94],['Location',91],['Service',97]].map(x=>`<div style="display:grid;grid-template-columns:90px 1fr 32px;gap:8px;align-items:center;margin-top:10px;font-size:10px;color:var(--muted)"><span>${x[0]}</span><div class="progress" style="margin:0;background:var(--line)"><span style="width:${x[1]}%"></span></div><span>${x[1]}%</span></div>`).join('')}</div><div class="reviews" style="margin-top:14px">${reviews.map(x=>`<div class="review"><div class="review-head"><strong>${x.name}</strong><span class="rating">${'★'.repeat(x.rating)}</span></div><small class="muted">${x.date}</small><p>${x.text}</p></div>`).join('')}</div>${state.user?`<button class="btn btn-outline" style="margin-top:14px" data-action="write-review">Write a review</button>`:`<p class="muted">Sign in after a stay to share your review.</p>`}</div></div><aside class="booking-card"><div class="room-meta"><span>Starting at</span>${statusTag(r.status)}</div><div class="price" style="margin-top:7px">${money(r.price)} <small>/ night</small></div><div class="field"><label>Check in</label><input type="date" id="detail-in" min="${todayISO()}" value="${datePlus(1)}"></div><div class="field"><label>Check out</label><input type="date" id="detail-out" min="${datePlus(2)}" value="${datePlus(2)}"></div><div class="field"><label>Guests</label><select id="detail-guests">${Array.from({length:r.capacity},(_,i)=>`<option>${i+1} guest${i?'s':''}</option>`).join('')}</select></div><div class="summary-line"><span>Estimated total · 1 night</span><strong id="detail-total">${money(Math.round(r.price*1.12))}</strong></div><button class="btn btn-primary" data-action="book" data-id="${r.id}">Reserve your stay　→</button><small class="muted" style="display:block;text-align:center;margin-top:10px">You will not be charged yet</small></aside></div></div></section>`}
function calendarHTML(r){return `<div class="dash-card" style="padding:15px;max-width:390px"><div style="display:grid;grid-template-columns:repeat(7,1fr);text-align:center;margin-bottom:5px">${['S','M','T','W','T','F','S'].map(x=>`<span class="muted" style="font-size:9px;padding:5px">${x}</span>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-0;const n=d+1;const busy=r.booked.includes(n);return `<span class="${busy?'busy':'free'}" style="font-size:10px;padding:7px 0;color:${n>30?'var(--line)':''}">${n<=30?n:''}</span>`}).join('')}</div><div style="display:flex;gap:13px;font-size:9px;color:var(--muted)"><span><i style="display:inline-block;width:8px;height:8px;background:var(--green-bg)"></i> Available</span><span><i style="display:inline-block;width:8px;height:8px;background:var(--red-bg)"></i> Booked</span></div></div>`}
/* AUTH */
function authPage(register=false){return `<section class="auth-shell"><div class="auth-card"><div class="auth-top"><a class="brand" href="#" data-page="home"><span class="brand-icon">🏨</span><span><span class="stay">Stay</span><span class="ease">Ease</span></span></a><button class="icon-btn" data-action="theme" aria-label="Toggle color theme">${state.theme==='dark'?'☀':'☾'}</button></div><span class="eyebrow">${register?'A warmer welcome':'Your stay, all in one place'}</span><h1>${register?'Make yourself at home.':'Welcome back.'}</h1><p>${register?'Create your StayEase account and let the good part of getting away begin.':'Sign in to manage your reservations, save your favorite rooms, and pick up where you left off.'}</p><form id="auth-form" data-register="${register}">${register?`<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" autocomplete="name" placeholder="e.g. Jordan Lee" required><div class="inline-error" data-error="name"></div></div>`:''}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required><div class="inline-error" data-error="email"></div></div><div class="field"><label for="auth-password">Password</label><div class="input-row"><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 8 characters':'Your password'}" minlength="8" required><button class="pw-toggle" type="button" data-action="toggle-password">Show</button></div>${register?`<div class="strength"><span id="strength-fill"></span></div><small id="strength-label" class="muted"></small>`:''}<div class="inline-error" data-error="password"></div></div>${register?`<div class="field"><label for="auth-confirm">Confirm password</label><input id="auth-confirm" name="confirm" type="password" placeholder="Enter your password again" required><div class="inline-error" data-error="confirm"></div></div>`:`<div style="text-align:right"><button type="button" class="btn btn-ghost btn-sm" data-action="forgot">Forgot password?</button></div>`}<div class="inline-error" data-error="form"></div><button class="btn btn-primary" type="submit">${register?'Create my account':'Sign in'}　→</button></form><div class="auth-switch">${register?'Already have an account?':'New to StayEase?'} <a href="#" data-page="${register?'login':'register'}">${register?'Sign in':'Create an account'}</a></div>${!register?`<div class="demo-note">Sign in to manage your stays. New here? Create an account to get started.</div>`:''}</div></section>`}
/* CUSTOMER + ADMIN DASHBOARD */
function dashboardPage(){if(!state.user)return authRedirect();return state.user.role==='admin'?adminDashboard():customerDashboard()}
function authRedirect(){setTimeout(()=>navigate('login'),0);return `<section class="page"><div class="wrap"><p>Please sign in to continue.</p></div></section>`}
function dashSide(admin=false){const tabs=admin?['Overview','Room Control','Bookings','Customers','Reports','Settings']:['Bookings','Favorites','Reviews','Loyalty','Profile'];return `<aside class="dash-side"><div class="dash-profile"><div class="avatar">${initials(state.user.name)}</div><div><strong>${esc(state.user.name)}</strong><small>${state.user.role==='admin'?'StayEase administrator':'Guest member'}</small></div></div><nav class="dash-nav">${tabs.map(t=>`<button class="${(admin?state.adminTab:state.customerTab)===t?'active':''}" data-action="${admin?'admin-tab':'customer-tab'}" data-tab="${t}">${t==='Bookings'?'▣':t==='Favorites'?'♡':t==='Reviews'?'✎':t==='Loyalty'?'✧':t==='Profile'?'◉':t==='Overview'?'⌂':t==='Room Control'?'▦':t==='Customers'?'♙':t==='Reports'?'▤':'⚙'}　${t}</button>`).join('')}<button data-action="logout">↪　Sign out</button></nav></aside>`}
function customerDashboard(){let body='';if(state.customerTab==='Bookings')body=customerBookings();if(state.customerTab==='Favorites')body=customerFavorites();if(state.customerTab==='Reviews')body=customerReviews();if(state.customerTab==='Loyalty')body=customerLoyalty();if(state.customerTab==='Profile')body=customerProfile();return `<section class="page"><div class="wrap"><div class="dash-layout">${dashSide()}<div class="dash-main"><h1>Good ${new Date().getHours()<12?'morning':'day'}, ${esc(state.user.name.split(' ')[0])}.</h1>${state.customerTab==='Bookings'?`<div class="dash-stats">${[['Your stays','4'],['Coming up','2'],['Lifetime spend','$2,657'],['StayEase points',state.user.points||2480]].map((x,i)=>`<div class="dash-stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>`:''}${body}</div></div></div></section>`}
function customerBookings(){const groups=state.bookingTab==='Upcoming'?bookings.filter(b=>b.status==='Confirmed'):state.bookingTab==='Past'?bookings.filter(b=>b.status==='Completed'):state.bookingTab==='Cancelled'?bookings.filter(b=>b.status==='Cancelled'):bookings;return `<div class="dash-card"><div class="dash-card-head"><h3>Your stays</h3><button class="btn btn-primary btn-sm" data-page="rooms">Find a room　→</button></div><div class="tabbar">${['Upcoming','Past','Cancelled','All'].map(t=>`<button class="${state.bookingTab===t?'active':''}" data-action="booking-tab" data-tab="${t}">${t}</button>`).join('')}</div>${groups.length?groups.map(b=>`<div class="booking-row"><div><strong>${b.room}</strong><small>Reservation ${b.id}</small></div><div>${b.dates}<small>${b.guest===state.user.name?'Your reservation':'StayEase reservation'}</small></div><div>${statusTag(b.status)}<small>${money(b.total)} total</small></div><div>${b.status==='Confirmed'?`<button class="btn btn-outline btn-sm" data-action="modify-booking" data-id="${b.id}">Modify</button> <button class="btn btn-danger btn-sm" data-action="cancel-booking" data-id="${b.id}">Cancel</button>`:''}</div></div>`).join(''):`<div class="empty-state"><div>✧</div><h3 class="serif">Nothing here for now.</h3><p>Your next favorite stay could be just around the corner.</p><button class="btn btn-primary" data-page="rooms">Explore rooms</button></div>`}</div><div class="dash-card"><div class="dash-card-head"><h3>For your next getaway</h3><span class="tag gold">A little treat</span></div><p class="muted" style="font-size:12px">Use your member code <strong style="color:var(--gold-dark)">STAY15</strong> for 15% off a stay of three nights or more.</p></div>`}
function customerFavorites(){const fav=rooms.filter(r=>state.favorites.has(r.id));return `<div class="dash-card"><div class="dash-card-head"><h3>Your saved rooms</h3><button class="btn btn-outline btn-sm" data-page="rooms">Discover more</button></div>${fav.length?`<div class="room-grid">${fav.map(roomCard).join('')}</div>`:`<div class="empty-state"><div>♡</div><h3 class="serif">Keep the rooms that feel like you.</h3><p>Tap the heart on any room to save it for another day.</p><button class="btn btn-primary" data-page="rooms">Find your room</button></div>`}</div>`}
function customerReviews(){return `<div class="dash-card"><div class="dash-card-head"><h3>Your notes from the road</h3></div><div class="empty-state"><div>✎</div><h3 class="serif">Your next story is still unwritten.</h3><p>After your stay, come back and share what made it special.</p></div></div>`}
function customerLoyalty(){const pts=state.user.points||2480;return `<div class="loyalty"><div class="loyalty-box"><span class="eyebrow" style="color:#e8c97a">StayEase Circle</span><h2 class="serif" style="font-size:31px;margin:12px 0">Gold member</h2><p style="font-size:11px;color:#ffffffad">Thoughtful little extras, just for you.</p><div style="font:600 25px 'Playfair Display'">${pts.toLocaleString()} <small style="font:11px 'DM Sans'">points</small></div><div class="progress"><span style="width:${Math.min(100,pts/40)}%"></span></div><small style="color:#ffffffaa">${Math.max(0,4000-pts).toLocaleString()} points to Platinum</small></div><div class="dash-card"><h3>Make your points go further.</h3><p class="muted" style="font-size:11px;line-height:1.6">Earn 10 points for every dollar spent and unlock the little extras that make a lovely stay even better.</p></div></div><div class="dash-card" style="margin-top:15px"><div class="dash-card-head"><h3>Your rewards</h3><span class="tag gold">${pts.toLocaleString()} points</span></div><div class="booking-row"><div><strong>Late checkout</strong><small>Stay a little longer</small></div><div>1,500 points</div><div><span class="tag green">Available</span></div><button class="btn btn-outline btn-sm" data-action="reward">Redeem</button></div><div class="booking-row"><div><strong>Welcome breakfast</strong><small>A slower start to the day</small></div><div>2,000 points</div><div><span class="tag green">Available</span></div><button class="btn btn-outline btn-sm" data-action="reward">Redeem</button></div><div class="booking-row"><div><strong>Spa afternoon</strong><small>Time just for you</small></div><div>4,000 points</div><div><span class="tag gold">Coming soon</span></div></div></div><div class="dash-card"><h3>Recent points</h3><div class="booking-row"><div><strong>Stay at The Garden Suite</strong><small>October 2026</small></div><div>+ 1,250 points</div><span class="tag green">Earned</span></div></div>`}
function customerProfile(){return `<div class="dash-card"><div class="dash-card-head"><h3>Your details</h3><button class="btn btn-outline btn-sm" data-action="edit-profile">${state.profileEdit?'Cancel':'Edit details'}</button></div><div class="field"><label>Full name</label><input id="profile-name" value="${esc(state.user.name)}" ${state.profileEdit?'':'disabled'}></div><div class="field"><label>Email address</label><input value="${esc(state.user.email)}" disabled></div><div class="field"><label>Phone number</label><input id="profile-phone" value="${esc(state.user.phone||'')}" ${state.profileEdit?'':'disabled'} placeholder="Add a phone number"></div>${state.profileEdit?`<button class="btn btn-primary" data-action="save-profile">Save changes</button>`:''}</div><div class="dash-card"><div class="dash-card-head"><h3>Your preferences</h3></div>${[['Stay updates','A little note about your reservation'],['Thoughtful offers','Occasional offers, selected for you'],['Member news','The latest from our StayEase Circle']].map((x,i)=>`<div class="booking-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><label class="check-label"><input type="checkbox" ${i<2?'checked':''}> On</label></div>`).join('')}<button class="btn btn-outline btn-sm" data-action="password-change" style="margin-top:15px">Change password</button></div>`}
function adminDashboard(){let content='';switch(state.adminTab){case'Overview':content=adminOverview();break;case'Room Control':content=adminRooms();break;case'Bookings':content=adminBookings();break;case'Customers':content=adminCustomers();break;case'Reports':content=adminReports();break;case'Settings':content=adminSettings();break}return `<section class="page"><div class="wrap"><div class="dash-layout">${dashSide(true)}<div class="dash-main"><h1>${state.adminTab==='Overview'?'Good morning, Avery.':state.adminTab}</h1>${content}</div></div></div></section>`}
function adminOverview(){return `<div class="dash-stats admin-stats">${[['Revenue this month','$84,290'],['Occupancy','78%'],['Arrivals today','12'],['Guest satisfaction','4.9 / 5']].map(x=>`<div class="dash-stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="admin-charts"><div class="dash-card"><div class="dash-card-head"><h3>Revenue overview</h3><div class="view-switch"><button class="${state.chartMode!=='line'?'active':''}" data-action="chart-mode" data-mode="bar">Bar</button><button class="${state.chartMode==='line'?'active':''}" data-action="chart-mode" data-mode="line">Line</button></div></div>${revenueChart()}</div><div class="dash-card"><div class="dash-card-head"><h3>Room occupancy</h3><span class="tag green">This month</span></div><div class="donut-wrap"><div class="donut"></div><div class="legend"><span><i style="background:#c9a84c"></i>Occupied · 62%</span><span><i style="background:#78917e"></i>Available · 25%</span><span><i style="background:#bb7161"></i>Maintenance · 13%</span></div></div></div></div><div class="admin-charts"><div class="dash-card"><div class="dash-card-head"><h3>Today's board</h3><span class="tag gold">November 9, 2026</span></div><div class="today-grid"><div class="today-box"><strong>12</strong><small>Arrivals</small></div><div class="today-box"><strong>8</strong><small>Departures</small></div><div class="today-box"><strong>86</strong><small>In-house guests</small></div></div><div class="dash-card-head" style="margin-top:24px"><h3>Recent bookings</h3><button class="btn btn-ghost btn-sm" data-action="admin-tab" data-tab="Bookings">See all →</button></div>${bookings.slice(0,3).map(b=>`<div class="booking-row"><div><strong>${b.guest}</strong><small>${b.id}</small></div><div>${b.room}</div><div>${statusTag(b.status)}</div></div>`).join('')}</div><div class="dash-card"><div class="dash-card-head"><h3>Recent activity</h3></div><div class="activity">${[['A new reservation was confirmed for The Garden Suite','8 min ago'],['Room 204 marked ready for arrival','25 min ago'],['A new five-star guest review was received','1 hr ago'],['Ocean Terrace booking modified','2 hrs ago']].map(x=>`<div class="activity-item"><i></i><div>${x[0]}<br><small>${x[1]}</small></div></div>`).join('')}</div></div></div>`}
function revenueChart(){const vals=[46,62,52,78,69,92,74,108,84,115,96,129];const months=['Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov'];if(state.chartMode==='line')return `<div class="chart"><svg viewBox="0 0 600 220" role="img" aria-label="Revenue line chart"><path class="chart-grid" d="M40 20H590M40 65H590M40 110H590M40 155H590M40 200H590"/>${vals.map((v,i)=>`<text x="${46+i*47}" y="216">${months[i]}</text>`).join('')}<polyline class="chart-line" points="${vals.map((v,i)=>`${48+i*47},${195-v*1.35}`).join(' ')}"/>${vals.map((v,i)=>`<circle class="chart-dot" cx="${48+i*47}" cy="${195-v*1.35}" r="5"><title>${months[i]} · $${v}k</title></circle>`).join('')}</svg></div>`;return `<div class="chart"><svg viewBox="0 0 600 220" role="img" aria-label="Revenue bar chart"><path class="chart-grid" d="M40 20H590M40 65H590M40 110H590M40 155H590M40 200H590"/>${vals.map((v,i)=>`<rect class="chart-bar" x="${48+i*46}" y="${195-v*1.28}" width="24" height="${v*1.28}"><title>${months[i]} · $${v}k</title></rect><text x="${45+i*46}" y="216">${months[i]}</text>`).join('')}</svg></div>`}
function adminRooms(){return `<div class="dash-card"><div class="dash-card-head"><h3>Room control</h3><button class="btn btn-primary btn-sm" data-action="add-room">＋ Add a room</button></div><div class="field" style="max-width:290px;margin-bottom:15px"><input placeholder="Search rooms…" id="room-search" value="${esc(state.roomSearch)}"></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Room</th><th>Type</th><th>Rate</th><th>Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rooms.filter(r=>r.name.toLowerCase().includes(state.roomSearch.toLowerCase())).map(r=>`<tr><td><strong>${r.emoji} ${r.name}</strong></td><td>${r.type}</td><td>${money(r.price)}</td><td>${r.capacity}</td><td><select class="control" data-room-status="${r.id}" style="width:125px;padding:7px;font-size:10px">${['Available','Occupied','Maintenance'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="btn btn-outline btn-sm" data-action="edit-room" data-id="${r.id}">Edit</button> <button class="btn btn-danger btn-sm" data-action="delete-room" data-id="${r.id}">×</button></td></tr>`).join('')}</tbody></table></div></div>`}
function adminBookings(){return `<div class="dash-card"><div class="dash-card-head"><h3>Reservations</h3><button class="btn btn-outline btn-sm" data-action="export-csv">↓ Export CSV</button></div><div class="filter-panel" style="margin-bottom:15px;padding:10px"><div class="field"><label>Search guest or ID</label><input id="booking-search" placeholder="Search…"></div><div class="field"><label>Status</label><select id="admin-booking-status"><option>All</option><option>Confirmed</option><option>Completed</option><option>Cancelled</option></select></div><div class="field"><label>From</label><input type="date"></div><div class="field"><label>To</label><input type="date"></div></div><div class="table-scroll"><table class="data-table" id="admin-booking-table"><thead><tr><th>Reservation</th><th>Guest</th><th>Room</th><th>Stay dates</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>${bookings.map(b=>`<tr data-status="${b.status}" data-search="${b.id} ${b.guest} ${b.room}"><td><strong>${b.id}</strong></td><td>${b.guest}</td><td>${b.room}</td><td>${b.dates}</td><td>${money(b.total)}</td><td>${statusTag(b.status)}</td><td>${b.status==='Confirmed'?`<button class="btn btn-outline btn-sm" data-action="approve-booking" data-id="${b.id}">✓</button> <button class="btn btn-danger btn-sm" data-action="admin-cancel" data-id="${b.id}">×</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></div>`}
function adminCustomers(){return `<div class="dash-card"><div class="dash-card-head"><h3>Guests</h3><span class="tag gold">1,248 members</span></div><div class="field" style="max-width:310px;margin-bottom:15px"><input id="customer-search" placeholder="Search guests…" value="${esc(state.customerSearch)}"></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Guest</th><th>Email</th><th>Visits</th><th>Total spent</th><th>Member since</th><th></th></tr></thead><tbody>${[['Olivia Martin','olivia@example.com','6','$4,280','2024'],['James Wilson','james@example.com','4','$3,150','2025'],['Aisha Patel','aisha@example.com','3','$2,890','2025'],['Noah Kim','noah@example.com','2','$1,130','2026'],['Sofia Ramirez','sofia@example.com','9','$7,920','2023']].filter(x=>x.join(' ').toLowerCase().includes(state.customerSearch.toLowerCase())).map(x=>`<tr><td><strong><span class="avatar" style="width:28px;height:28px;display:inline-grid;vertical-align:middle;margin-right:6px">${initials(x[0])}</span>${x[0]} ${+x[3].replace(/\D/g,'')>4000?'<span class="tag gold">VIP</span>':''}</strong></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td><button class="btn btn-outline btn-sm" data-action="customer-detail" data-name="${x[0]}">View</button></td></tr>`).join('')}</tbody></table></div></div>`}
function adminReports(){return `<div class="dash-stats admin-stats">${[['Monthly revenue','$84,290'],['Top room type','Suites'],['Cancellation rate','2.4%'],['Average length','3.2 nights']].map(x=>`<div class="dash-stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="dash-card"><div class="dash-card-head"><h3>Revenue by room type</h3><span class="tag gold">Year to date</span></div>${[['Suites',82],['Deluxe',68],['Family',56],['Premium',44],['Standard',31]].map(x=>`<div style="display:grid;grid-template-columns:85px 1fr 50px;gap:12px;align-items:center;margin:15px 0;font-size:11px"><span>${x[0]}</span><div class="progress" style="margin:0;background:var(--line)"><span style="width:${x[1]}%"></span></div><strong>${money(x[1]*930)}</strong></div>`).join('')}</div><div class="dash-card"><h3>Guest experience</h3><p class="muted" style="font-size:12px;line-height:1.7">Guest satisfaction is holding at <strong style="color:var(--gold-dark)">4.9 / 5</strong>, up 0.2 points from this time last year. The most mentioned highlights are our team, restful rooms, and the breakfast experience.</p></div>`}
function adminSettings(){return `<div class="dash-card"><div class="dash-card-head"><h3>Hotel details</h3></div><div class="field"><label>Hotel name</label><input id="hotel-name" value="StayEase Hotel"></div><div class="field"><label>Default tax rate</label><input id="tax-rate" type="number" value="12" min="0" max="30"></div><button class="btn btn-primary" data-action="save-settings">Save settings</button></div><div class="dash-card"><div class="dash-card-head"><h3>Promotional codes</h3><button class="btn btn-outline btn-sm" data-action="add-promo">＋ Add code</button></div><div class="booking-row"><div><strong>STAY15</strong><small>15% off stays of 3 nights or more</small></div><span class="tag green">Active</span><button class="btn btn-outline btn-sm" data-action="toggle-promo">Pause</button></div><div class="booking-row"><div><strong>WELCOME10</strong><small>10% off first reservation</small></div><span class="tag gold">Scheduled</span><button class="btn btn-outline btn-sm" data-action="toggle-promo">Edit</button></div></div>`}
/* BOOKING FLOW + MODALS */
function startBooking(id){const r=getRoom(id);if(!r)return;if(!state.user){state.pendingRoom=id;state.modal={kind:'login-gate',roomId:id};render();return}state.bookingDraft={roomId:r.id,room:r.name,checkin:$('#detail-in')?.value||datePlus(1),checkout:$('#detail-out')?.value||datePlus(2),guests:+($('#detail-guests')?.value?.match(/\d+/)?.[0]||state.guests),extras:[],promo:'',discount:0,payment:'Credit card',card:'',expiry:'',guest:state.user.name,email:state.user.email};state.bookingStep=1;state.modal={kind:'booking'};render()}
function calcDraft(){const d=state.bookingDraft||{},r=getRoom(d.roomId)||rooms[0],n=nights(d.checkin,d.checkout),subtotal=r.price*n+(d.extras||[]).reduce((s,x)=>s+({Breakfast:24,'Airport pickup':48,'Late checkout':35,'Spa package':95}[x]||0)*n,0),discount=Math.round(subtotal*(d.discount||0)),tax=Math.round((subtotal-discount)*.12);return {r,n,subtotal,discount,tax,total:subtotal-discount+tax}}
function bookingModal(){const d=state.bookingDraft,c=calcDraft(),step=state.bookingStep;let main='';if(step===1)main=`<h3 class="serif" style="margin:0 0 15px">When shall we welcome you?</h3><div class="field"><label>Check in</label><input type="date" id="book-in" min="${todayISO()}" value="${d.checkin}"></div><div class="field" style="margin-top:13px"><label>Check out</label><input type="date" id="book-out" min="${datePlus(2)}" value="${d.checkout}"></div><div class="field" style="margin-top:13px"><label>Guests</label><select id="book-guests">${Array.from({length:c.r.capacity},(_,i)=>`<option value="${i+1}" ${d.guests===i+1?'selected':''}>${i+1} guest${i?'s':''}</option>`).join('')}</select></div><p class="muted" style="font-size:10px">Free cancellation up to 48 hours before arrival.</p>`;if(step===2)main=`<h3 class="serif" style="margin:0 0 6px">Make it a little more special.</h3><p class="muted" style="font-size:11px">Choose a few thoughtful extras for your stay.</p>${[['Breakfast','A slow start, delivered to your room','24'],['Airport pickup','A smooth arrival, from door to door','48'],['Late checkout','An extra hour or two to settle in','35'],['Spa package','A restorative treatment for two','95']].map(x=>`<div class="addon"><label><input type="checkbox" data-extra="${x[0]}" ${(d.extras||[]).includes(x[0])?'checked':''}><span><strong>${x[0]}</strong><small>${x[1]}</small></span></label><strong>${money(x[2])}</strong></div>`).join('')}<div class="field" style="margin-top:16px"><label>Promo code</label><div style="display:flex;gap:7px"><input id="promo-input" placeholder="Enter a code" value="${esc(d.promo)}"><button class="btn btn-outline btn-sm" data-action="apply-promo">Apply</button></div><div class="inline-error" id="promo-error">${d.discount?`Applied — 15% off`:''}</div></div>`;if(step===3)main=`<h3 class="serif" style="margin:0 0 6px">A few details to confirm.</h3><p class="muted" style="font-size:11px">Your payment is securely simulated for this demo.</p><div class="field"><label>Payment method</label><select id="payment-method"><option>Credit card</option><option>Pay at the hotel</option></select></div><div class="field" style="margin-top:12px"><label>Name on reservation</label><input id="book-guest" value="${esc(d.guest)}"></div><div class="field" style="margin-top:12px"><label>Email for confirmation</label><input id="book-email" type="email" value="${esc(d.email)}"></div>${d.payment!=='Pay at the hotel'?`<div class="field" style="margin-top:12px"><label>Card number</label><input id="card-number" inputmode="numeric" maxlength="19" placeholder="4242 4242 4242 4242" value="${esc(d.card)}"></div><div class="field" style="display:flex;gap:10px;margin-top:12px"><div style="flex:1"><label>Expiry</label><input id="card-expiry" placeholder="MM/YY" maxlength="5" value="${esc(d.expiry)}"></div><div style="flex:1"><label>Security code</label><input id="card-cvc" inputmode="numeric" maxlength="4" placeholder="CVC"></div></div>`:''}<div class="inline-error" id="payment-error"></div>`;if(step===4)main=`<div style="text-align:center;padding:12px 0"><div style="font-size:55px">✧</div><span class="eyebrow">Your escape is on the calendar</span><h2 class="serif" style="font-size:32px;margin:12px 0">It's official, ${esc((d.guest||'friend').split(' ')[0])}.</h2><p class="muted" style="font-size:12px">Your reservation <strong>${d.bookingId||''}</strong> is confirmed. A little something from us is on its way to your inbox.</p></div><div class="dash-card"><div class="booking-row"><div><strong>${d.room}</strong><small>${d.checkin} → ${d.checkout}</small></div><div>${d.guests} guests</div><div><strong>${money(c.total)}</strong><small>Total with taxes</small></div></div></div><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button class="btn btn-outline btn-sm" data-action="invoice">↓ Download invoice</button><button class="btn btn-outline btn-sm" data-action="calendar-download">＋ Add to calendar</button></div><div class="confetti">${Array.from({length:22},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${(i%8)*.12}s;background:${['#c9a84c','#e8c97a','#819c82','#c47b68'][i%4]}"></i>`).join('')}</div>`;return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" data-stop><div class="modal-head"><div><h2>${step===4?'Reservation confirmed':`Reserve ${esc(d.room)}`}</h2>${step<4?`<small class="muted">Step ${step} of 3</small>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${step<4?`<div class="step-track">${[1,2,3].map(n=>`<span class="${n<=step?'done':''}"></span>`).join('')}</div><div class="booking-grid"><div>${main}</div>${summaryHTML(c)}</div>`:main}</div><div class="modal-foot">${step===4?`<button class="btn btn-outline" data-action="close-modal">Close</button><button class="btn btn-primary" data-page="dashboard">View my stays　→</button>`:`<button class="btn btn-outline" data-action="booking-back" ${step===1?'disabled':''}>${step===1?'Keep looking':'← Back'}</button><button class="btn btn-primary" data-action="booking-next">${step===3?'Confirm and reserve':'Continue　→'}</button>`}</div></div></div>`}
function summaryHTML(c){return `<aside class="booking-summary"><strong>${c.r.emoji}　${c.r.name}</strong><p class="muted" style="font-size:10px;margin:7px 0">${state.bookingDraft.checkin} → ${state.bookingDraft.checkout} · ${c.n} night${c.n===1?'':'s'}</p><div class="summary-line"><span>${money(c.r.price)} × ${c.n} nights</span><span>${money(c.r.price*c.n)}</span></div>${(state.bookingDraft.extras||[]).length?`<div class="summary-line"><span>Selected extras</span><span>${money(c.subtotal-c.r.price*c.n)}</span></div>`:''}${c.discount?`<div class="summary-line" style="color:var(--green)"><span>STAY15 discount</span><span>−${money(c.discount)}</span></div>`:''}<div class="summary-line"><span>Taxes & fees</span><span>${money(c.tax)}</span></div><div class="summary-line total"><span>Total</span><span>${money(c.total)}</span></div></aside>`}
function modalHTML(){if(state.modal.kind==='booking')return bookingModal();if(state.modal.kind==='compare'){const list=[...state.compare].map(getRoom);return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" data-stop><div class="modal-head"><h2>Find the right fit</h2><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Room</th>${list.map(r=>`<th>${r.name}</th>`).join('')}</tr></thead><tbody>${[['From',...list.map(r=>money(r.price)+' / night')],['Type',...list.map(r=>r.type)],['Sleeps',...list.map(r=>r.capacity+' guests')],['Rating',...list.map(r=>'★ '+r.rating)],['Highlights',...list.map(r=>r.amenities.join(', '))]].map(row=>`<tr>${row.map((x,i)=>`<td>${i===0?`<strong>${x}</strong>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="modal-foot"><button class="btn btn-outline" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="book" data-id="${list[0]?.id}">Book a room</button></div></div></div>`}if(state.modal.kind==='login-gate')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" style="width:min(430px,100%)" data-stop><div class="modal-head"><h2>Save your stay</h2><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body"><p class="muted" style="font-size:13px;line-height:1.7">Sign in or create an account to reserve ${getRoom(state.modal.roomId)?.name||'this room'} and keep all your plans in one place.</p></div><div class="modal-foot"><button class="btn btn-outline" data-action="close-modal">Keep looking</button><button class="btn btn-primary" data-page="login">Sign in　→</button></div></div></div>`;if(state.modal.kind==='confirm')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" style="width:min(430px,100%)" data-stop><div class="modal-head"><h2>${state.modal.title}</h2><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body"><p class="muted" style="font-size:13px;line-height:1.7">${state.modal.message}</p></div><div class="modal-foot"><button class="btn btn-outline" data-action="close-modal">Go back</button><button class="btn btn-danger" data-action="confirm-modal">${state.modal.confirmText||'Confirm'}</button></div></div></div>`;if(state.modal.kind==='generic')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" style="width:min(500px,100%)" data-stop><div class="modal-head"><h2>${state.modal.title}</h2><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body">${state.modal.body}</div><div class="modal-foot"><button class="btn btn-outline" data-action="close-modal">Close</button>${state.modal.submit?`<button class="btn btn-primary" data-action="generic-submit">Save changes</button>`:''}</div></div></div>`;if(state.modal.kind==='forgot')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" style="width:min(420px,100%)" data-stop><div class="modal-head"><h2>A fresh start</h2><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body"><p class="muted" style="font-size:12px">Enter your email and we will send a mock password reset link.</p><div class="field"><label>Email</label><input id="forgot-email" type="email" placeholder="you@example.com"></div></div><div class="modal-foot"><button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="forgot-submit">Send reset link</button></div></div></div>`;return''}
function render(){document.body.classList.toggle('dark',state.theme==='dark');let content=state.page==='home'?homePage():state.page==='rooms'?roomsPage():state.page==='details'?detailsPage():state.page==='login'?authPage(false):state.page==='register'?authPage(true):state.page==='dashboard'?dashboardPage():homePage();$('#app').innerHTML=appShell(content);afterRender()}
function afterRender(){const bar=$('#topbar');if(bar)bar.classList.toggle('scrolled',window.scrollY>12);observeReveal();if(state.page==='home'){setTimeout(animateCounters,250)}if(state.page==='details'){for(const id of ['detail-in','detail-out'])$('#'+id)?.addEventListener('change',updateDetailTotal);updateDetailTotal()}}
function animateCounters(){if(state.page!=='home')return;$$('[data-count]').forEach(el=>{const target=+el.dataset.count,suffix=el.dataset.suffix||'',start=performance.now(),duration=1100;function tick(t){const p=Math.min(1,(t-start)/duration);el.textContent=Math.round(target*(1-Math.pow(1-p,3))).toLocaleString()+suffix;if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
function observeReveal(){if(!('IntersectionObserver'in window)){ $$('.reveal').forEach(x=>x.classList.add('visible'));return}const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(x=>io.observe(x))}
/* NAVIGATION */
function navigate(page,id){if(page==='dashboard'&&!state.user){state.page='login';state.modal=null;render();return}state.page=page;state.mobile=false;state.modal=null;if(id)state.roomId=+id;window.scrollTo({top:0,behavior:'smooth'});if(page==='rooms'&&!state.roomsLoaded){state.roomsLoading=true;render();api.getRooms(state.searchDates?{check_in:state.searchDates.cin,check_out:state.searchDates.cout}:{}).then(items=>{rooms.splice(0,rooms.length,...items);state.roomsLoaded=true;state.roomsLoading=false;if(state.page==='rooms')render()});return}render()}
function updateDetailTotal(){const r=getRoom(state.roomId);if(!r)return;const n=nights($('#detail-in')?.value||datePlus(1),$('#detail-out')?.value||datePlus(2));const el=$('#detail-total');if(el)el.textContent=money(Math.round(r.price*n*1.12))}
function openConfirm(title,message,confirmText,callback){state.modal={kind:'confirm',title,message,confirmText,callback};render()}
function modalUpdate(){const m=state.modal;render();state.modal=m}
/* EVENTS */
document.addEventListener('click',async e=>{const rip=e.target.closest('.btn');if(rip){const rr=rip.getBoundingClientRect();rip.style.setProperty('--ripple-x',(e.clientX-rr.left)+'px');rip.style.setProperty('--ripple-y',(e.clientY-rr.top)+'px');rip.classList.remove('rippling');void rip.offsetWidth;rip.classList.add('rippling');setTimeout(()=>rip.classList.remove('rippling'),520)}const stop=e.target.closest('[data-stop]');const backdrop=e.target.closest('.modal-backdrop');if(stop&&backdrop&&e.target.closest('[data-action]')===backdrop)return;const p=e.target.closest('[data-page]');if(p){e.preventDefault();const page=p.dataset.page;if(page==='details')navigate('details',p.dataset.id||state.roomId);else navigate(page);return}const sc=e.target.closest('[data-scroll]');if(sc){e.preventDefault();state.mobile=false;render();setTimeout(()=>document.getElementById(sc.dataset.scroll)?.scrollIntoView({behavior:'smooth'}),50);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=+b.dataset.id;
if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';render()}else if(a==='mobile'){state.mobile=!state.mobile;render()}else if(a==='logout'){api.logout();state.user=null;bookings=[];state.favorites.clear();toast('You have signed out.','success');navigate('home')}else if(a==='notifications'){if(!state.notifications&&state.user){try{const noteData=await api.getNotifications();state.notificationsList=noteData.items||[]}catch(err){toast(err.message,'error')}}state.notifications=!state.notifications;render()}else if(a==='close-notifications'){state.notifications=false;render()}else if(a==='close-modal'){state.modal=null;render()}else if(a==='guest-plus'||a==='guest-minus'){state.guests=Math.max(1,Math.min(8,state.guests+(a==='guest-plus'?1:-1)));render()}else if(a==='search'){const cin=$('#search-in')?.value,cout=$('#search-out')?.value;if(!cin||!cout||cout<=cin){toast('Please choose a check-out date after check-in.','error');return}state.filters.type=$('#search-type')?.value||'All types';state.searchDates={cin,cout};state.filters.capacity=state.guests;state.roomsLoaded=false;navigate('rooms')}else if(a==='favorite'){if(!state.user){toast('Sign in to save your favorite rooms.','info');return}try{if(state.favorites.has(id)){await api.removeFavorite(id);state.favorites.delete(id)}else{await api.addFavorite(id);state.favorites.add(id)}const was=state.page;render();if(was==='home')window.scrollTo({top:window.scrollY,behavior:'instant'})}catch(err){toast(err.message,'error')}}else if(a==='book'){if(!id)return;startBooking(id)}else if(a==='hero'){state.hero=+b.dataset.index;render()}else if(a==='testimonial-next'||a==='testimonial-prev'){state.testimonial=(state.testimonial+(a==='testimonial-next'?1:2))%3;render()}else if(a==='faq'){state.faqOpen=state.faqOpen===+b.dataset.index?null:+b.dataset.index;render()}else if(a==='copy-promo'){try{await navigator.clipboard.writeText('STAY15');toast('Code STAY15 copied.','success')}catch{toast('Your code is STAY15.','success')}}else if(a==='toggle-filter-more'){state.filterMore=!state.filterMore;render()}else if(a==='clear-filters'){state.filters={type:'All types',status:'All',min:0,max:800,capacity:1,amenities:[],sort:'Recommended'};state.searchDates=null;render()}else if(a==='view-grid'||a==='view-list'){state.view=a==='view-grid'?'grid':'list';render()}else if(a==='compare'){if(state.compare.size<2){toast('Choose at least two rooms to compare.','info');return}state.modal={kind:'compare'};render()}else if(a==='clear-compare'){state.compare.clear();render()}else if(a==='toggle-password'){const input=$('#auth-password');if(input){input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide'}}else if(a==='forgot'){state.modal={kind:'forgot'};render()}else if(a==='forgot-submit'){const email=$('#forgot-email')?.value;if(!/^\S+@\S+\.\S+$/.test(email||'')){toast('Please enter a valid email.','error');return}state.modal=null;render();toast('Reset link sent to '+email+'.','success')}else if(a==='customer-tab'){state.customerTab=b.dataset.tab;render()}else if(a==='admin-tab'){state.adminTab=b.dataset.tab;render()}else if(a==='booking-tab'){state.bookingTab=b.dataset.tab;render()}else if(a==='booking-back'){if(state.bookingStep>1){state.bookingStep--;render()}else{state.modal=null;render()}}else if(a==='booking-next'){await nextBookingStep()}else if(a==='apply-promo'){const code=$('#promo-input')?.value||'';try{await api.applyPromo(code);state.bookingDraft.promo=code.toUpperCase();state.bookingDraft.discount=.15;render();toast('STAY15 applied — 15% off.','success')}catch(err){$('#promo-error').textContent=err.message;toast(err.message,'error')}}else if(a==='confirm-modal'){const m=state.modal;state.modal=null;render();if(m.callback)await m.callback()}else if(a==='cancel-booking'){openConfirm('Cancel this stay?','Your reservation will be cancelled. This cannot be undone.','Cancel reservation',async()=>{await api.cancelBooking(b.dataset.id);const item=bookings.find(x=>x.id===b.dataset.id);if(item)item.status='Cancelled';render();toast('Reservation cancelled.','success')})}else if(a==='admin-cancel'){openConfirm('Cancel reservation?','This will cancel the guest reservation.','Cancel reservation',async()=>{const item=bookings.find(x=>x.id===b.dataset.id);if(item)item.status='Cancelled';render();toast('Reservation cancelled.','success')})}else if(a==='approve-booking'){toast('Reservation confirmed and guest notified.','success')}else if(a==='modify-booking'){state.modal={kind:'generic',title:'Modify your dates',submit:true,body:`<div class="field"><label>New check in</label><input id="modify-in" type="date" value="${datePlus(2)}"></div><div class="field" style="margin-top:12px"><label>New check out</label><input id="modify-out" type="date" value="${datePlus(4)}"></div>`};state.genericSubmit=()=>toast('Date change request saved.','success');render()}else if(a==='edit-profile'){state.profileEdit=!state.profileEdit;render()}else if(a==='save-profile'){state.user.name=$('#profile-name').value;state.user.phone=$('#profile-phone').value;state.profileEdit=false;render();toast('Your details have been saved.','success')}else if(a==='password-change'){state.modal={kind:'generic',title:'Change password',submit:true,body:`<div class="field"><label>Current password</label><input type="password" id="old-password"></div><div class="field" style="margin-top:12px"><label>New password</label><input type="password" id="new-password"></div>`};state.genericSubmit=()=>toast('Password updated for this demo session.','success');render()}else if(a==='reward'){toast('Reward reserved for your next stay.','success')}else if(a==='chart-mode'){state.chartMode=b.dataset.mode;render()}else if(a==='edit-room'){const r=getRoom(id);state.modal={kind:'generic',title:'Edit '+r.name,submit:true,body:`<div class="field"><label>Room name</label><input id="edit-room-name" value="${esc(r.name)}"></div><div class="field" style="margin-top:12px"><label>Nightly rate</label><input id="edit-room-price" type="number" value="${r.price}"></div><div class="field" style="margin-top:12px"><label>Room type</label><select id="edit-room-type">${['Standard','Deluxe','Premium','Suite','Family'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select></div>`};state.genericSubmit=()=>{r.name=$('#edit-room-name').value;r.price=+$('#edit-room-price').value;r.type=$('#edit-room-type').value;toast('Room updated.','success')};render()}else if(a==='add-room'){state.modal={kind:'generic',title:'Add a room',submit:true,body:`<div class="field"><label>Room name</label><input id="new-room-name" placeholder="e.g. Willow Suite"></div><div class="field" style="margin-top:12px"><label>Room type</label><select id="new-room-type">${['Standard','Deluxe','Premium','Suite','Family'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Nightly rate</label><input id="new-room-price" type="number" placeholder="250"></div><div class="field" style="margin-top:12px"><label>Guest capacity</label><input id="new-room-capacity" type="number" value="2"></div>`};state.genericSubmit=()=>{rooms.push({id:Math.max(...rooms.map(r=>r.id))+1,name:$('#new-room-name').value||'New room',type:$('#new-room-type').value,price:+$('#new-room-price').value||250,capacity:+$('#new-room-capacity').value||2,rating:4.8,reviews:0,status:'Available',emoji:'🛏️',art:'linear-gradient(135deg,#ddd0b8,#9c8765)',amenities:['King bed','Coffee bar','WiFi'],description:'A thoughtful new room, ready to welcome our guests.',booked:[]});toast('New room added.','success')};render()}else if(a==='delete-room'){const r=getRoom(id);openConfirm('Remove '+r.name+'?','This room will be removed from the available room list.','Remove room',async()=>{const i=rooms.findIndex(x=>x.id===id);if(i>=0)rooms.splice(i,1);render();toast('Room removed.','success')})}else if(a==='export-csv'){const csv='Reservation,Guest,Room,Dates,Total,Status\n'+bookings.map(b=>[b.id,b.guest,b.room,b.dates,b.total,b.status].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');download('stayease-bookings.csv',csv,'text/csv');toast('Bookings exported.','success')}else if(a==='customer-detail'){const name=b.dataset.name;state.modal={kind:'generic',title:name,body:`<p class="muted" style="font-size:12px">Guest profile · member since 2024</p><div class="dash-card"><strong>Recent reservations</strong><p style="font-size:11px">The Garden Suite · Nov 18–21 · Confirmed</p><p style="font-size:11px">Ocean Terrace · Jul 06–09 · Completed</p><strong>Guest preference</strong><p style="font-size:11px">Garden views · Late checkout</p></div>`};render()}else if(a==='save-settings'){toast('Hotel settings saved.','success')}else if(a==='add-promo'){state.modal={kind:'generic',title:'Add promotional code',submit:true,body:`<div class="field"><label>Promo code</label><input id="new-promo" placeholder="WELCOME15"></div><div class="field" style="margin-top:12px"><label>Discount percentage</label><input id="new-promo-percent" type="number" value="10"></div>`};state.genericSubmit=()=>toast('Promotional code added.','success');render()}else if(a==='toggle-promo'){toast('Promotion setting updated.','success')}else if(a==='generic-submit'){if(state.genericSubmit)state.genericSubmit();state.genericSubmit=null;state.modal=null;render()}else if(a==='write-review'){state.modal={kind:'generic',title:'Share your experience',submit:true,body:`<div class="field"><label>Your rating</label><select id="review-rating"><option>5</option><option>4</option><option>3</option></select></div><div class="field" style="margin-top:12px"><label>Your note</label><textarea id="review-note" rows="4" placeholder="What made your stay special?"></textarea></div>`};state.genericSubmit=async()=>{await api.submitReview({room:state.roomId,rating:+$('#review-rating').value,text:$('#review-note').value});toast('Thank you for sharing your note.','success')};render()}else if(a==='invoice'){downloadInvoice()}else if(a==='calendar-download'){downloadCalendar()}else if(a==='close-notifications'){state.notifications=false;render()}else if(a==='toggle-promo')toast('Promotion updated.','success');else if(a==='back-top'){window.scrollTo({top:0,behavior:'smooth'})}
});
document.addEventListener('change',e=>{const f=e.target.dataset.filter;if(f){state.filters[f]=f==='max'||f==='capacity'?+e.target.value:e.target.value;render();return}if(e.target.dataset.amenity){const v=e.target.dataset.amenity;if(e.target.checked)state.filters.amenities.push(v);else state.filters.amenities=state.filters.amenities.filter(x=>x!==v);render();return}if(e.target.dataset.compare){const id=+e.target.dataset.compare;if(e.target.checked){if(state.compare.size>=3){e.target.checked=false;toast('You can compare up to three rooms.','info');return}state.compare.add(id)}else state.compare.delete(id);render();return}if(e.target.dataset.extra){const x=e.target.dataset.extra;if(e.target.checked)state.bookingDraft.extras.push(x);else state.bookingDraft.extras=state.bookingDraft.extras.filter(a=>a!==x);modalUpdate();return}if(e.target.id==='book-in'||e.target.id==='book-out'||e.target.id==='book-guests'){const d=state.bookingDraft;if(e.target.id==='book-in')d.checkin=e.target.value;if(e.target.id==='book-out')d.checkout=e.target.value;if(e.target.id==='book-guests')d.guests=+e.target.value;render();return}if(e.target.id==='detail-in'||e.target.id==='detail-out')updateDetailTotal();if(e.target.id==='payment-method'){state.bookingDraft.payment=e.target.value;render()}if(e.target.id==='room-search'){state.roomSearch=e.target.value;render()}if(e.target.id==='customer-search'){state.customerSearch=e.target.value;render()}if(e.target.id==='booking-search'||e.target.id==='admin-booking-status'){const term=$('#booking-search')?.value.toLowerCase()||'',status=$('#admin-booking-status')?.value||'All';$$('#admin-booking-table tbody tr').forEach(tr=>tr.classList.toggle('hidden',!tr.dataset.search.toLowerCase().includes(term)||(status!=='All'&&tr.dataset.status!==status)))}if(e.target.dataset.roomStatus){getRoom(+e.target.dataset.roomStatus).status=e.target.value;toast('Room status updated.','success')}});
document.addEventListener('input',e=>{if(e.target.id==='auth-password'&&$('#strength-fill')){const v=e.target.value;let score=0;if(v.length>=6)score++;if(/[A-Z]/.test(v)&&/[a-z]/.test(v))score++;if(/\d/.test(v))score++;if(/[^A-Za-z0-9]/.test(v))score++;$('#strength-fill').style.width=score*25+'%';$('#strength-fill').style.background=score<2?'var(--red)':score<4?'var(--gold)':'var(--green)';$('#strength-label').textContent=['Add more characters for a stronger password.','A little more length would help.','Getting stronger.','Strong password.','Excellent password.'][score]}if(e.target.id==='card-number'){e.target.value=e.target.value.replace(/\D/g,'').slice(0,16).replace(/(.{4})/g,'$1 ').trim();state.bookingDraft.card=e.target.value}if(e.target.id==='card-expiry'){let v=e.target.value.replace(/\D/g,'').slice(0,4);if(v.length>2)v=v.slice(0,2)+'/'+v.slice(2);e.target.value=v;state.bookingDraft.expiry=v}});
document.addEventListener('submit',async e=>{if(e.target.id==='newsletter-form'){e.preventDefault();const email=new FormData(e.target).get('email');try{await api.subscribeNewsletter(email);e.target.reset();toast('You are on the list. See you in your inbox.','success')}catch(err){toast(err.message,'error')}}if(e.target.id==='auth-form'){e.preventDefault();const fd=new FormData(e.target),register=e.target.dataset.register==='true',email=String(fd.get('email')).trim(),password=String(fd.get('password')),name=String(fd.get('name')||'').trim(),err=(key,msg)=>{const el=$(`[data-error="${key}"]`);if(el)el.textContent=msg||''};$$('.inline-error').forEach(x=>x.textContent='');if(register&&!name){err('name','Please enter your name.');return}if(!/^\S+@\S+\.\S+$/.test(email)){err('email','Please enter a valid email address.');return}if(password.length<8){err('password','Use at least 8 characters.');return}if(register&&password!==fd.get('confirm')){err('confirm','Your passwords do not match.');return}const submit=$('button[type="submit"]',e.target);submit.disabled=true;submit.textContent=register?'Creating your account…':'Signing you in…';try{state.user=register?await api.register(name,email,password):await api.login(email,password);await loadDashboardData();if(state.pendingRoom){const rid=state.pendingRoom;state.pendingRoom=null;toast(`Welcome, ${state.user.name.split(' ')[0]}. Let's get your stay sorted.`,'success');startBooking(rid);return}toast(`Welcome ${register?'to StayEase':'back'}, ${state.user.name.split(' ')[0]}.`,'success');navigate('dashboard')}catch(errx){err('form',errx.message);submit.disabled=false;submit.textContent=register?'Create my account':'Sign in'}}});
async function nextBookingStep(){const d=state.bookingDraft;if(state.bookingStep===1){const a=$('#book-in').value,b=$('#book-out').value;if(!a||!b||b<=a){toast('Check-out needs to be after check-in.','error');return}const r=getRoom(d.roomId);const busy=r.booked.some(day=>{const start=new Date(a),end=new Date(b),date=new Date(start.getFullYear(),start.getMonth(),day);return start.getMonth()===10&&start.getFullYear()===2026&&date>=start&&date<end})||bookings.some(x=>x.roomId===r.id&&x.status==='Confirmed'&&a<x.checkout&&b>x.checkin);if(busy){toast('One or more of those dates are already booked. Please choose another stay.','error');return}d.checkin=a;d.checkout=b;d.guests=+$('#book-guests').value;state.bookingStep=2;render();return}if(state.bookingStep===2){state.bookingStep=3;render();return}if(state.bookingStep===3){d.payment=$('#payment-method').value;d.guest=$('#book-guest').value.trim();d.email=$('#book-email').value.trim();d.card=$('#card-number')?.value||'';d.expiry=$('#card-expiry')?.value||'';if(!d.guest||!/^\S+@\S+\.\S+$/.test(d.email)){toast('Please add a name and valid email address.','error');return}if(d.payment==='Credit card'&&(d.card.replace(/\D/g,'').length<15||!/^\d{2}\/\d{2}$/.test(d.expiry)||!$('#card-cvc')?.value)){toast('Please complete the card details.','error');return}const btn=$('.modal-foot .btn-primary');if(btn){btn.disabled=true;btn.textContent='Securing your stay…'}try{await api.processPayment();const res=await api.createBooking({...d,...calcDraft(),dates:`${d.checkin} – ${d.checkout}`,total:calcDraft().total});d.bookingId=res.id;bookings.unshift({...res,guest:d.guest,email:d.email,roomId:d.roomId,status:'Confirmed'});state.bookingStep=4;render()}catch(err){toast(err.message,'error');if(btn){btn.disabled=false;btn.textContent='Confirm and reserve'}}}}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function downloadInvoice(){const d=state.bookingDraft;try{const response=await api.invoice(d.bookingId);download('stayease-invoice-'+d.bookingId+'.html',await response.text(),'text/html')}catch(err){toast(err.message,'error')}return;const c=calcDraft();const html=`<!doctype html><html><head><meta charset="utf-8"><title>StayEase invoice ${d.bookingId}</title><style>body{font:15px Arial;color:#28241e;padding:50px;max-width:760px;margin:auto}h1{font:36px Georgia;color:#a07830}.line{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding:12px 0}.total{font-size:20px;font-weight:bold}</style></head><body><h1>StayEase</h1><p>Reservation invoice · ${d.bookingId}</p><h2>${d.room}</h2><p>${d.guest} · ${d.email}</p><p>${d.checkin} to ${d.checkout} · ${c.n} night(s)</p><div class="line"><span>Room and extras</span><span>${money(c.subtotal)}</span></div><div class="line"><span>Discount</span><span>−${money(c.discount)}</span></div><div class="line"><span>Taxes and fees</span><span>${money(c.tax)}</span></div><div class="line total"><span>Total</span><span>${money(c.total)}</span></div><p>Thank you for choosing StayEase.</p><script>window.print()<\/script></body></html>`;download(`stayease-invoice-${d.bookingId}.html`,html,'text/html')}
function downloadCalendar(){const d=state.bookingDraft;const ics=`BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//StayEase//Stay//EN\nBEGIN:VEVENT\nUID:${d.bookingId}@stayease.com\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z')}\nDTSTART;VALUE=DATE:${d.checkin.replaceAll('-','')}\nDTEND;VALUE=DATE:${d.checkout.replaceAll('-','')}\nSUMMARY:StayEase — ${d.room}\nDESCRIPTION:Reservation ${d.bookingId}\nEND:VEVENT\nEND:VCALENDAR`;download(`stayease-${d.bookingId}.ics`,ics,'text/calendar')}
async function loadInitialData(){try{const list=await api.getRooms();rooms.splice(0,rooms.length,...list);state.roomsLoaded=true;const reviewResults=await Promise.all(rooms.map(room=>api.getRoomReviews(room.id).catch(()=>({items:[]}))));reviews.splice(0,reviews.length,...reviewResults.flatMap(result=>result.items||[]).map(item=>({name:item.name||item.user||'StayEase guest',date:item.created_at?new Date(item.created_at).toLocaleDateString(undefined,{month:'long',year:'numeric'}):'',rating:item.rating,text:item.comment||item.text||''})));if(api.token()){try{state.user=await api.me();await loadDashboardData()}catch(err){api.logout();state.user=null}}render()}catch(err){toast(err.message,'error')}}
async function loadDashboardData(){
  if(!state.user)return;
  try{
    if(state.user.role==='admin'){const [statsResult,bookingResult,customerResult]=await Promise.all([api.getAdminStats(),api.getAdminBookings(),api.getAdminCustomers()]);state.adminStats=statsResult;bookings=bookingResult.items||[];state.customers=customerResult.items||[]}
    else{const [bookingResult,favoriteResult]=await Promise.all([api.getBookings(),api.getFavorites()]);bookings=bookingResult;state.favorites=new Set(favoriteResult.map(room=>room.id))}
    const notes=await api.getNotifications();state.notificationsList=notes.items||[];render()
  }catch(err){toast(err.message,'error')}
}
window.addEventListener('stayease:auth-expired',()=>{state.user=null;bookings=[];state.favorites.clear();if(state.page==='dashboard')navigate('login');else render()});
