window.addEventListener('scroll',()=>{const t=$('#topbar');if(t)t.classList.toggle('scrolled',window.scrollY>12);$('#back-top').classList.toggle('show',window.scrollY>450)});$('#back-top')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal){state.modal=null;render()}if(state.notifications){state.notifications=false;render()}}if(e.key==='Enter'&&e.target.id==='auth-password')$('#auth-form')?.requestSubmit()});setInterval(()=>{if(state.page==='home'&&!state.modal&&!document.activeElement.matches('input,textarea,select')){state.hero=(state.hero+1)%3;render()}},8000);setInterval(()=>{if(state.page==='home'&&!state.modal&&!document.activeElement.matches('input,textarea,select')){state.testimonial=(state.testimonial+1)%3;render()}},6500);render();loadInitialData();
